import i18n from '@dhis2/d2-i18n'
import { InputFieldFF } from '@dhis2/ui'
import React from 'react'
import { Field } from 'react-final-form'
import { StandardFormField } from '../../../../../components'
import { useLabelValidator } from './useLabelValidator'

export function OrgUnitLabelField() {
    const validate = useLabelValidator('orgUnitLabel')

    return (
        <StandardFormField>
            <Field
                component={InputFieldFF}
                name="orgUnitLabel"
                inputWidth="400px"
                label={i18n.t('Custom label for "Registering unit"')}
                helpText={i18n.t(
                    'Used to customize the label for the organisation unit that registers the enrollment or event'
                )}
                dataTest="formfields-orgUnitLabel"
                validate={validate}
            />
        </StandardFormField>
    )
}
